window.AUTH=window.AUTH||{};window.AUTH["19-177"]={"d":"19-177","id":"2019/19-177","n":"United States Agency for International Development v. Alliance for Open Society International, Inc.","briefs":[{"k":"petitioner","label":"Brief of petitioners United States Agency for Intrnational Development, et al.","date":"2020-01-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-177/130086/20200127190929205_19-177tsUnitedStates.pdf","side":"pet","n":67},{"k":"respondent","label":"Brief of respondents Alliance for Open Society International, Inc., et al.","date":"2020-02-26","url":"https://www.supremecourt.gov/DocketPDF/19/19-177/134286/20200226195038592_19-177%20bs.pdf","side":"res","n":43},{"k":"reply","label":"Reply of petitioners Agency for International Development, et al.","date":"2020-03-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-177/138113/20200313141651696_19-177rbUnitedStates.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US1PP_web.pdf#page=440","tr":true,"items":[{"t":"case","label":"Balintulo v. Ford Motor Co.","cite":"796 F.3d 160","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/796/160/","sum":"Explaining that veil-piercing may be appropriate where a “corporate parent excessively dominates its subsidiary in such a way as to make it a mere instrumentality of the parent”.","sumSrc":"brief:0","by":{"0":"30"}},{"t":"case","label":"Braswell v. United States","cite":"487 U.S. 99","y":1988,"id":"1987/87-3","sc":1,"sum":"The Supreme Court held that corporations are not protected by the Fifth Amendment privilege against self-incrimination. An agent of the corporation holds the official records of the corporation in their representative, and not individual, capacity so the personal privilege is not applicable.","sumSrc":"Oyez","by":{"0":"24, 28"}},{"t":"case","label":"(III) Cases—Continued: Cedric Kushner Promotions, Ltd. v. King","cite":"533 U.S. 158","y":2001,"id":"2000/00-549","sc":1,"op":2,"sum":"The Court held that \"the need for two distinct entities is satisfied; hence, the RICO provision...applies when a corporate employee unlawfully conducts the affairs of the corporation of which he is the sole owner -- whether he conducts those affairs within the scope, or beyond the scope, of corporate authority.\" \"The corporate owner/employee, a natural person, is distinct from the corporation itself, a legally different entity,\" wrote Justice Breyer. \"A corporate employee who conducts the corporation's affairs through an unlawful RICO 'pattern...of activity,' uses that corporation as a 'vehicle' whether he is, or is not, its sole owner.\".","sumSrc":"Oyez","by":{"0":"28","1":"43"}},{"t":"case","label":"Center for Reprod. Law & Policy v. Bush","cite":"304 F.3d 183","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/304/183/","by":{"0":"26, 32","1":"50","2":"19"}},{"t":"case","label":"Cooper Indus., Inc. v. Aviall Servs., Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"DKT Mem’l Fund Ltd. v. Agency for Int’l Dev.","cite":"887 F.2d 275","y":1989,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/887/275/","by":{"0":"26, 32","1":"50"}},{"t":"case","label":"Daimler AG v. Bauman","cite":"571 U.S. 117","y":2014,"id":"2013/11-965","sc":1,"sum":"The Court held the judiciary did not have jurisdiction over DaimlerChrysler AG in California because the conduct in question was not in the state.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"op":4,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"0":"28, 30, 31","1":"37, 43"}},{"t":"case","label":"FCC v. League of Women Voters","cite":"468 U.S. 364","y":1984,"id":"1983/82-912","sc":1,"op":10,"sum":"Observing that funding conditions that restrict speech can survive constitutional scrutiny if the speaker may “make known its views on matters of public importance through” a legally separate Breyer, J., dissenting affliate—and if not, not.","sumSrc":"opinion","by":{"0":"23","1":"15, 32"}},{"t":"case","label":"Guardians Ass’n v. Civil Serv. Comm’n","cite":"463 U.S. 582","y":1983,"id":"1982/81-431","sc":1,"sum":"The judgment is affirmed. 633 F. 2d 232, affirmed. JUSTICE WHITE concluded that discriminatory intent is not an essential element of a Title VI violation. JUSTICE WHITE, joined by JUSTICE REHNQUIST, also concluded that a private plaintiff should recover only injunctive, noncompensatory relief for a defendant's unintentional violation of Title VI, that such relief should not include an award of constructive …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Janus Capital Grp., Inc. v. First Derivative Traders","cite":"564 U.S. 135","y":2011,"id":"2010/09-525","sc":1,"sum":"The Court held that a service provider cannot be held liable for statements for which they are not directly responsible.","sumSrc":"Oyez","by":{"0":"28, 31","1":"43"}},{"t":"case","label":"Johnson v. Eisentrager","cite":"339 U.S. 763","y":1950,"id":"scdb/1949-091","sc":1,"op":6,"sum":"-Respondents, who are nonresident enemy aliens, were captured in China by the United States Army and tried and convicted in China by an American military commission for-violations of the laws of war committed in China prior to their capture. They were transported to the American-occupied part of Germany and imprisoned there in the custody of the Army. At no time were they within the territorial jurisdiction of any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"op":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Koontz v. St. Johns River Water Mgmt. Dist.","cite":"570 U.S. 595","y":2013,"id":"2012/11-1447","sc":1,"op":24,"sum":"Concluding that speech uttered involuntarily by legally separate affliates may be attributed to respondents if the affliates are “clearly identifed” with respondents.","sumSrc":"opinion","by":{"0":"23"}},{"t":"case","label":"Kowalski v. Tesmer","cite":"543 U.S. 125","y":2004,"id":"2004/03-407","sc":1,"sum":"The Court held that the attorneys lacked third-party standing to sue on behalf of the Michigan indigent defendants. The attorneys did not have close relationships with the indigent defendants, nor was there a hindrance to these defendants' ability to advance their own constitutional rights against the Michigan scheme.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Planned Parenthood Fed’n of Am., Inc. v. Agency for Int’l Dev.","cite":"915 F.2d 59","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/915/59/","sum":"Finding “no constitutional rights implicated” by a funding condition applied to foreign entities operating abroad.","sumSrc":"brief:0","by":{"0":"26, 32","1":"50","2":"19"}},{"t":"case","label":"Regan v. Taxation With Representation of Washington","cite":"461 U.S. 540","y":1983,"id":"1982/81-2338","sc":1,"op":16,"ar":2,"sum":"No and no. Justice William H. Rehnquist authored the opinion for a unanimous court. Allowing a non-profit to solicit tax-deductible donations is a form of paying for its operations.","sumSrc":"Oyez","by":{"0":"23, 29, 31","1":"3, 15, 23, 28, 40","2":"16, 17"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"op":3,"ar":1,"sum":"Holding that the Government may require law schools to host speech from military recruiters.","sumSrc":"opinion","by":{"0":"22, 24, 39","1":"42","2":"11, 12, 17, 20"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"op":2,"ar":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"22, 23, 29","1":"2, 3, 15, 16, 27, 28, 32","2":"12, 18"}},{"t":"case","label":"Schenley Distillers Corp. v. United States","cite":"326 U.S. 432","y":1946,"id":"scdb/1945-098","sc":1,"sum":"In order to obtain a determination as to whether it was a \"contract carrier by motor vehicle\" as defined by § 203 (a) (15) of Part II of the Interstate Commerce Act or a \"private carrier of property by motor vehicle\" as defined by § 203 (a) (17), one of the appellants applied to the Interstate Commerce Commission for a permit under § 209 (b) to operate as a \"contract carrier.\" In the proceedings before the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","2":"15"}},{"t":"case","label":"South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"op":1,"sum":"The Court ruled that Congress did not exceed its spending powers or violate the Twenty-First Amendment when it conditioned the award of federal highway funds on states' adoption of a uniform minimum drinking age.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Sumitomo Shoji Am., Inc. v. Avagliano","cite":"457 U.S. 176","y":1982,"id":"1981/80-2070","sc":1,"sum":"Sumitomo is not a company of Japan and thus is not covered by Art. VIII(l) of the Treaty.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"United States v. American Library Ass’n, Inc.","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"sum":"In a 6-3 judgment delivered by Chief Justice William H. Rehnquist, the Court held that, because public libraries' use of Internet filtering software does not violate their patrons' First Amendment rights, CIPA does not induce libraries to violate the Constitution and is a valid exercise of Congress's spending power. Justices Sandra Day O'Connor, Antonin Scalia, and Clarence Thomas joined the Chief Justice's opinion.","sumSrc":"Oyez","by":{"0":"22, 24"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"United States v. Verdugo-Urquidez","cite":"494 U.S. 259","y":1990,"id":"1989/88-1353","sc":1,"op":5,"sum":"The text of the Fourth Amendment concerns \"the people,\" suggesting a concern with persons who are part of the national community, as contrasted with aliens without any substantial connection to the U.S. Moreover, extraterritorial aliens are not even entitled to rights under the Fifth Amendment, which speaks in the relatively more universal term of \"person.\" And non-\"fundamental\" rights are not even guaranteed to inhabitants of unincorporated territories under U.S sovereign control, much less aliens.","sumSrc":"Oyez","by":{"0":"24, 25"}},{"t":"case","label":"United States ex rel. Turner v. Williams","cite":"194 U.S. 279","y":1904,"id":"scdb/1903-104","sc":1,"op":3,"sum":"Congress has power to exclude aliens from, and to prescribe the conditions on which they may enter, the United States; to establish regulations for deporting aliens who have illegally entered, and to commit the enforcements of such conditions and regulations to executive officers. Deporting, pursuant to law, an alien who has illegally entered the United States, does not deprive him of his liberty without due process …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"0":"21"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","2":"8, 16, 17, 19"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 116-94","url":"https://www.govinfo.gov/link/plaw/116/public/94","by":{"0":"31"}},{"t":"law","label":"Pub. L. No. 115-305","url":"https://www.govinfo.gov/link/plaw/115/public/305","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 113-56","url":"https://www.govinfo.gov/link/plaw/113/public/56","by":{"0":"6"}},{"t":"law","label":"Pub. L. No. 110-293","url":"https://www.govinfo.gov/link/plaw/110/public/293","by":{"0":"6"}},{"t":"usc","label":"22 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/22/7101","by":{"0":"41"}},{"t":"usc","label":"22 U.S.C. § 7110","url":"https://www.law.cornell.edu/uscode/text/22/7110","subs":["(g)(1)"],"by":{"0":"41"}},{"t":"usc","label":"22 U.S.C. § 7601","url":"https://www.law.cornell.edu/uscode/text/22/7601","subs":["(1)","(2)","(3)(B)","(4)","(6)","(18)","(23)","(25)","(29)"],"stext":{"head":"§7601. Findings","paras":[[0,"Congress makes the following findings:"],[1,"(1) During the last 20 years, HIV/AIDS has assumed pandemic proportions, spreading from the most severely affected regions, sub-Saharan Africa and the Caribbean, to all corners of the world, and leaving an unprecedented path of death and devastation."],[1,"(2) According to the Joint United Nations Programme on HIV/AIDS (UNAIDS), more than 65,000,000 individuals worldwide have been infected with HIV since the epidemic began, more than 25,000,000 of these individuals have lost their lives to the disease, and more than 14,000,000 children have been orphaned by the disease. HIV/AIDS is the fourth-highest cause of death in the world."],[1,"(3)(A) At the end of 2002, an estimated 42,000,000 individuals were infected with HIV or living with AIDS, of which more than 75 percent live in Africa or the Caribbean. Of these individuals, more than 3,200,000 were children under the age of 15 and more than 19,200,000 were women."],[1,"(B) Women are four times more vulnerable to infection than are men and are becoming infected at increasingly high rates, in part because many societies do not provide poor women and young girls with the social, legal, and cultural protections against high risk activities that expose them to HIV/AIDS."],[1,"(C) Women and children who are refugees or are internally displaced persons are especially vulnerable to sexual exploitation and violence, thereby increasing the possibility of HIV infection."],[1,"(4) As the leading cause of death in sub-Saharan Africa, AIDS has killed more than 19,400,000 individuals (more than 3 times the number of AIDS deaths in the rest of the world) and will claim the lives of one-quarter of the population, mostly adults, in the next decade."],[1,"(5) An estimated 2,000,000 individuals in Latin America and the Caribbean and another 7,100,000 individuals in Asia and the Pacific region are infected with HIV or living with AIDS. Infection rates are rising alarmingly in Eastern Europe (especially in the Russian Federation), Central Asia, and China."],[1,"(6) HIV/AIDS threatens personal security by affecting the health, lifespan, and productive capacity of the individual and the social cohesion and economic well-being of the family."],[1,"(7) HIV/AIDS undermines the economic security of a country and individual businesses in that country by weakening the productivity and longevity of the labor force across a broad array of economic sectors and by reducing the potential for economic growth over the long term."],[1,"(8) HIV/AIDS destabilizes communities by striking at the most mobile and educated members of society, many of whom are responsible for security at the local level and governance at the national and subnational levels as well as many teachers, health care personnel, and other community workers vital to community development and the effort to combat HIV/AIDS. In some countries the overwhelming challenges of the HIV/AIDS epidemic are accelerating the outward migration of critically important health care professionals."],[1,"(9) HIV/AIDS weakens the defenses of countries severely affected by the HIV/AIDS crisis through high infection rates among members of their military forces and voluntary peacekeeping personnel. According to UNAIDS, in sub-Saharan Africa, many military forces have infection rates as much as five times that of the civilian population."],[1,"(10) HIV/AIDS poses a serious security issue for the international community by—"],[2,"(A) increasing the potential for political instability and economic devastation, particularly in those countries and regions most severely affected by the disease;"],[2,"(B) decreasing the capacity to resolve conflicts through the introduction of peacekeeping forces because the environments into which these forces are introduced pose a high risk for the spread of HIV/AIDS; and"],[2,"(C) increasing the vulnerability of local populations to HIV/AIDS in conflict zones from peacekeeping troops with HIV infection rates significantly higher than civilian populations."],[1,"(11) The devastation wrought by the HIV/AIDS pandemic is compounded by the prevalence of tuberculosis and malaria, particularly in developing countries where the poorest and most vulnerable members of society, including women, children, and those individuals living with HIV/AIDS, become infected. According to the World Health Organization (WHO), HIV/AIDS, tuberculosis, and malaria accounted for more than 5,700,000 deaths in 2001 and caused debilitating illnesses in millions more."],[1,"(12) Together, HIV/AIDS, tuberculosis, malaria and related diseases are undermining agricultural production throughout Africa. According to the United Nations Food and Agricultural Organization, 7,000,000 agricultural workers throughout 25 African countries have died from AIDS since 1985. Countries with poorly developed agricultural systems, which already face chronic food shortages, are the hardest hit, particularly in sub-Saharan Africa, where high HIV prevalence rates are compounding the risk of starvation for an estimated 14,400,000 people."],[1,"(13) Tuberculosis is the cause of death for one out of every three people with AIDS worldwide and is a highly communicable disease. HIV infection is the leading threat to tuberculosis control. Because HIV infection so severely weakens the immune system, individuals with HIV and latent tuberculosis infection have a 100 times greater risk of developing active tuberculosis diseases thereby increasing the risk of spreading tuberculosis to others. Tuberculosis, in turn, accelerates the onset of AIDS in individuals infected with HIV."],[1,"(14) Malaria, the most deadly of all tropical parasitic diseases, has been undergoing a dramatic resurgence in recent years due to increasing resistance of the malaria parasite to inexpensive and effective drugs. At the same time, increasing resistance of mosquitoes to standard insecticides makes control of transmission difficult to achieve. The World Health Organization estimates that between 300,000,000 and 500,000,000 new cases of malaria occur each year, and annual deaths from the disease number between 2,000,000 and 3,000,000. Persons infected with HIV are particularly vulnerable to the malaria parasite. The spread of HIV infection contributes to the difficulties of controlling resurgence of the drug resistant malaria parasite."],[1,"(15) HIV/AIDS is first and foremost a health problem. Successful strategies to stem the spread of the HIV/AIDS pandemic will require clinical medical interventions, the strengthening of health care delivery systems and infrastructure, and determined national leadership and increased budgetary allocations for the health sector in countries affected by the epidemic as well as measures to address the social and behavioral causes of the problem and its impact on families, communities, and societal sectors."],[1,"(16) Basic interventions to prevent new HIV infections and to bring care and treatment to people living with AIDS, such as voluntary counseling and testing and mother-to-child transmission programs, are achieving meaningful results and are cost-effective. The challenge is to expand these interventions from a pilot program basis to a national basis in a coherent and sustainable manner."],[1,"(17) Appropriate treatment of individuals with HIV/AIDS can prolong the lives of such individuals, preserve their families, prevent children from becoming orphans, and increase productivity of such individuals by allowing them to lead active lives and reduce the need for costly hospitalization for treatment of opportunistic infections caused by HIV."],[1,"(18) Nongovernmental organizations, including faith-based organizations, with experience in health care and HIV/AIDS counseling, have proven effective in combating the HIV/AIDS pandemic and can be a resource in assisting indigenous organizations in severely affected countries in their efforts to provide treatment and care for individuals infected with HIV/AIDS."],[1,"(19) Faith-based organizations are making an important contribution to HIV prevention and AIDS treatment programs around the world. Successful HIV prevention programs in Uganda, Jamaica, and elsewhere have included local churches and faith-based groups in efforts to promote behavior changes to prevent HIV, to reduce stigma associated with HIV infection, to treat those afflicted with the disease, and to care for orphans. The Catholic Church alone currently cares for one in four people being treated for AIDS worldwide. Faith-based organizations possess infrastructure, experience, and knowledge that will be needed to carry out these programs in the future and should be an integral part of United States efforts."],[1,"(20)(A) Uganda has experienced the most significant decline in HIV rates of any country in Africa, including a decrease among pregnant women from 20.6 percent in 1991 to 7.9 percent in 2000."],[1,"(B) Uganda made this remarkable turnaround because President Yoweri Museveni spoke out early, breaking long-standing cultural taboos, and changed widespread perceptions about the disease. His leadership stands as a model for ways political leaders in Africa and other developing countries can mobilize their nations, including civic organizations, professional associations, religious institutions, business and labor to combat HIV/AIDS."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/7601?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§7601. Findings","tname":"Foreign Relations and Intercourse","by":{"0":"2, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4","2":"1, 21"}},{"t":"usc","label":"22 U.S.C. § 7611","url":"https://www.law.cornell.edu/uscode/text/22/7611","subs":["(a)","(a)(12)","(a)(12)(F)","(a)(12)(H)","(a)(12)(J)"],"by":{"0":"4, 4, 4, 4, 4, 4"}},{"t":"usc","label":"22 U.S.C. § 7621","url":"https://www.law.cornell.edu/uscode/text/22/7621","subs":["(a)(4)"],"by":{"0":"4"}},{"t":"usc","label":"22 U.S.C. § 7631","url":"https://www.law.cornell.edu/uscode/text/22/7631","subs":["(e)"],"stext":{"head":"§7631. Assistance to combat HIV/AIDS","paras":[[0,"(a) Omitted"],[0,"(b) Authorization of appropriations"],[0,"(1) In general"],[1,"In addition to funds available under section 104(c) of the Foreign Assistance Act of 1961 (22 U.S.C. 2151b(c)) for such purpose or under any other provision of that Act [22 U.S.C. 2151 et seq.], there are authorized to be appropriated to the President, from amounts authorized to be appropriated under section 7671 of this title, such sums as may be necessary for each of the fiscal years 2009 through 2013 to carry out section 104A of the Foreign Assistance Act of 1961, as added by subsection (a) [22 U.S.C. 2151b–2]."],[0,"(2) Availability of funds"],[1,"Amounts appropriated pursuant to paragraph (1) are authorized to remain available until expended."],[0,"(3) Allocation of funds"],[1,"Of the amount authorized to be appropriated by paragraph (1) for the fiscal years 2009 through 2013, such sums as may be necessary are authorized to be appropriated to carry out section 104A(d)(4) of the Foreign Assistance Act of 1961 (as added by subsection (a)) [22 U.S.C. 2151b–2(d)(4)], relating to the procurement and distribution of HIV/AIDS pharmaceuticals."],[0,"(c) Food and nutritional support"],[0,"(1) In general"],[1,"As indicated in the report produced by the Institute of Medicine, entitled \"PEPFAR Implementation: Progress and Promise\", inadequate caloric intake has been clearly identified as a principal reason for failure of clinical response to antiretroviral therapy. In recognition of the impact of malnutrition as a clinical health issue for many persons living with HIV/AIDS that is often associated with health and economic impacts on these individuals and their families, the Global AIDS Coordinator and the Administrator of the United States Agency for International Development shall—"],[2,"(A) follow World Health Organization guidelines for HIV/AIDS food and nutrition services;"],[2,"(B) integrate nutrition programs with HIV/AIDS activities through effective linkages among the health, agricultural, and livelihood sectors and establish additional services in circumstances in which referrals are inadequate or impossible;"],[2,"(C) provide, as a component of care and treatment programs for persons with HIV/AIDS, food and nutritional support to individuals infected with, and affected by, HIV/AIDS who meet established criteria for nutritional support (including clinically malnourished children and adults, and pregnant and lactating women in programs in need of supplemental support), including—"],[3,"(i) anthropometric and dietary assessment;"],[3,"(ii) counseling; and"],[3,"(iii) therapeutic and supplementary feeding;"],[2,"(D) provide food and nutritional support for children affected by HIV/AIDS and to communities and households caring for children affected by HIV/AIDS; and"],[2,"(E) in communities where HIV/AIDS and food insecurity are highly prevalent, support programs to address these often intersecting health problems through community-based assistance programs, with an emphasis on sustainable approaches."],[0,"(2) Authorization of appropriations"],[1,"Of the amounts authorized to be appropriated under section 7671 of this title, there are authorized to be appropriated to the President such sums as may be necessary for each of the fiscal years 2009 through 2013 to carry out this subsection."],[0,"(d) Eligibility for assistance"],[0,"An organization, including a faith-based organization, that is otherwise eligible to receive assistance under section 104A of the Foreign Assistance Act of 1961 [22 U.S.C. 2151b–2], under this chapter, or under any amendment made by this chapter or by the Tom Lantos and Henry J. Hyde United States Global Leadership Against HIV/AIDS, Tuberculosis, and Malaria Reauthorization Act of 2008, for HIV/AIDS prevention, treatment, or care—"],[1,"(1) shall not be required, as a condition of receiving such assistance—"],[2,"(A) to endorse or utilize a multisectoral or comprehensive approach to combating HIV/AIDS; or"],[2,"(B) to endorse, utilize, make a referral to, become integrated with, or otherwise participate in any program or activity to which the organization has a religious or moral objection; and"],[1,"(2) shall not be discriminated against in the solicitation or issuance of grants, contracts, or cooperative agreements under such provisions of law for refusing to meet any requirement described in paragraph (1)."],[0,"(e) Limitation"],[0,"No funds made available to carry out this chapter, or any amendment made by this chapter, may be used to promote or advocate the legalization or practice of prostitution or sex trafficking. Nothing in the preceding sentence shall be construed to preclude the provision to individuals of palliative care, treatment, or post-exposure pharmaceutical prophylaxis, and necessary pharmaceuticals and commodities, including test kits, condoms, and, when proven effective, microbicides."],[0,"(f) Limitation"],[0,"No funds made available to carry out this chapter, or any amendment made by this chapter, may be used to provide assistance to any group or organization that does not have a policy explicitly opposing prostitution and sex trafficking, except that this subsection shall not apply to the Global Fund to Fight AIDS, Tuberculosis and Malaria, the World Health Organization, the International AIDS Vaccine Initiative or to any United Nations agency."],[0,"(g) Sense of Congress relating to food assistance for individuals living with HIV/AIDS"],[0,"(1) Findings"],[1,"Congress finds the following:"],[2,"(A) The United States provides more than 60 percent of all food assistance worldwide."],[2,"(B) According to the United Nations World Food Program and other United Nations agencies, food insecurity of individuals infected or living with HIV/AIDS is a major problem in countries with large populations of such individuals, particularly in African countries."],[2,"(C) Although the United States is willing to provide food assistance to these countries in need, a few of the countries object to part or all of the assistance because of fears of benign genetic modifications to the foods."],[2,"(D) Healthy and nutritious foods for individuals infected or living with HIV/AIDS are an important complement to HIV/AIDS medicines for such individuals."],[2,"(E) Individuals infected with HIV have higher nutritional requirements than individuals who are not infected with HIV, particularly with respect to the need for protein. Also, there is evidence to suggest that the full benefit of therapy to treat HIV/AIDS may not be achieved in individuals who are malnourished, particularly in pregnant and lactating women."],[0,"(2) Sense of Congress"],[1,"It is therefore the sense of Congress that United States food assistance should be accepted by countries with large populations of individuals infected or living with HIV/AIDS, particularly African countries, in order to help feed such individuals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/7631?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7631. Assistance to combat HIV/AIDS","tname":"Foreign Relations and Intercourse","by":{"0":"4, 4","2":"10, passim"}},{"t":"usc","label":"22 U.S.C. § 7671","url":"https://www.law.cornell.edu/uscode/text/22/7671","by":{"0":"4"}},{"t":"usc","label":"22 U.S.C. § 2151b-2","url":"https://www.law.cornell.edu/uscode/text/22/2151b-2","subs":["(b)(1)","(c)","(c)(2)"],"by":{"0":"32, 32, 32"}},{"t":"usc","label":"22 U.S.C. § 2271","url":"https://www.law.cornell.edu/uscode/text/22/2271","stext":{"head":"§2271. Statement of policy","paras":[[0,"(a) Congressional findings"],[0,"The Congress finds that—"],[1,"(1) the building of democracy, the restoration of peace, the improvement of living conditions, and the application of equal justice under law in Central America are important to the interests of the United States and the community of American States; and"],[1,"(2) the interrelated issues of social and human progress, economic growth, political reform, and regional security must be effectively dealt with to assure a democratic and economically and politically secure Central America."],[0,"(b) Policy requirements"],[0,"(1) The achievement of democracy, respect for human rights, peace, and equitable economic growth depends primarily on the cooperation and the human and economic resources of the people and governments of Central America. The Congress recognizes that the United States can make a significant contribution to such peaceful and democratic development through a consistent and coherent policy which includes a long-term commitment of assistance. This policy should be designed to support actively—"],[1,"(A) democracy and political reform, including opening the political process to all members of society;"],[1,"(B) full observance of internationally recognized human rights, including free elections, freedom of the press, freedom of association, and the elimination of all human rights abuses;"],[1,"(C) leadership development, including training and educational programs to improve public administration and the administration of justice;"],[1,"(D) land reform, reform in tax systems, encouragement of private enterprise and individual initiative, creation of favorable investment climates, curbing corruption where it exists, and spurring balanced trade;"],[1,"(E) the establishment of the rule of law and an effective judicial system; and"],[1,"(F) the termination of extremist violence by both the left and the right as well as vigorous action to prosecute those guilty of crimes and the prosecution to the extent possible of past offenders."],[0,"(2) The policy described in paragraph (1) should also promote equitable economic growth and development, including controlling the flight of capital and the effective use of foreign assistance and adhering to approved programs for economic stabilization and fiscal responsibility. Finally, this policy should foster dialog and negotiations—"],[1,"(A) to achieve peace based upon the objectives of democratization, reduction of armament, an end to subversion, and the withdrawal of foreign military forces and advisers; and"],[1,"(B) to provide a security shield against violence and intimidation."],[0,"(3) It is the purpose of this part to establish the statutory framework and to authorize the appropriations and financing necessary to carry out the policy described in this section."],[0,"(c) Additional Congressional findings"],[0,"The Congress finds, therefore, that the people of the United States are willing to sustain and expand a program of economic and military assistance in Central America if the recipient countries can demonstrate progress toward and a commitment to these goals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2271?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2271. Statement of policy","tname":"Foreign Relations and Intercourse","by":{"0":"32"}},{"t":"usc","label":"22 U.S.C. § 2272","url":"https://www.law.cornell.edu/uscode/text/22/2272","by":{"0":"32"}},{"t":"usc","label":"22 U.S.C. § 2371","url":"https://www.law.cornell.edu/uscode/text/22/2371","by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/26/501","subs":["(c)(3)","(c)(4)"],"stext":{"head":"§501. Exemption from tax on corporations, certain trusts, etc.","paras":[[0,"(a) Exemption from taxation"],[0,"An organization described in subsection (c) or (d) or section 401(a) shall be exempt from taxation under this subtitle unless such exemption is denied under section 502 or 503."],[0,"(b) Tax on unrelated business income and certain other activities"],[0,"An organization exempt from taxation under subsection (a) shall be subject to tax to the extent provided in parts II, III, and VI of this subchapter, but (notwithstanding parts II, III, and VI of this subchapter) shall be considered an organization exempt from income taxes for the purpose of any law which refers to organizations exempt from income taxes."],[0,"(c) List of exempt organizations"],[0,"The following organizations are referred to in subsection (a):"],[1,"(1) Any corporation organized under Act of Congress which is an instrumentality of the United States but only if such corporation—"],[2,"(A) is exempt from Federal income taxes—"],[3,"(i) under such Act as amended and supplemented before July 18, 1984, or"],[3,"(ii) under this title without regard to any provision of law which is not contained in this title and which is not contained in a revenue Act, or"],[2,"(B) is described in subsection (l)."],[1,"(2) Corporations organized for the exclusive purpose of holding title to property, collecting income therefrom, and turning over the entire amount thereof, less expenses, to an organization which itself is exempt under this section. Rules similar to the rules of subparagraph (G) of paragraph (25) shall apply for purposes of this paragraph."],[1,"(3) Corporations, and any community chest, fund, or foundation, organized and operated exclusively for religious, charitable, scientific, testing for public safety, literary, or educational purposes, or to foster national or international amateur sports competition (but only if no part of its activities involve the provision of athletic facilities or equipment), or for the prevention of cruelty to children or animals, no part of the net earnings of which inures to the benefit of any private shareholder or individual, no substantial part of the activities of which is carrying on propaganda, or otherwise attempting, to influence legislation (except as otherwise provided in subsection (h)), and which does not participate in, or intervene in (including the publishing or distributing of statements), any political campaign on behalf of (or in opposition to) any candidate for public office."],[1,"(4)(A) Civic leagues or organizations not organized for profit but operated exclusively for the promotion of social welfare, or local associations of employees, the membership of which is limited to the employees of a designated person or persons in a particular municipality, and the net earnings of which are devoted exclusively to charitable, educational, or recreational purposes."],[1,"(B) Subparagraph (A) shall not apply to an entity unless no part of the net earnings of such entity inures to the benefit of any private shareholder or individual."],[1,"(5) Labor, agricultural, or horticultural organizations."],[1,"(6) Business leagues, chambers of commerce, real-estate boards, boards of trade, or professional football leagues (whether or not administering a pension fund for football players), not organized for profit and no part of the net earnings of which inures to the benefit of any private shareholder or individual."],[1,"(7) Clubs organized for pleasure, recreation, and other nonprofitable purposes, substantially all of the activities of which are for such purposes and no part of the net earnings of which inures to the benefit of any private shareholder."],[1,"(8) Fraternal beneficiary societies, orders, or associations—"],[2,"(A) operating under the lodge system or for the exclusive benefit of the members of a fraternity itself operating under the lodge system, and"],[2,"(B) providing for the payment of life, sick, accident, or other benefits to the members of such society, order, or association or their dependents."],[1,"(9) Voluntary employees' beneficiary associations providing for the payment of life, sick, accident, or other benefits to the members of such association or their dependents or designated beneficiaries, if no part of the net earnings of such association inures (other than through such payments) to the benefit of any private shareholder or individual. For purposes of providing for the payment of sick and accident benefits to members of such an association and their dependents, the term \"dependent\" shall include any individual who is a child (as defined in section 152(f)(1)) of a member who as of the end of the calendar year has not attained age 27."],[1,"(10) Domestic fraternal societies, orders, or associations, operating under the lodge system—"],[2,"(A) the net earnings of which are devoted exclusively to religious, charitable, scientific, literary, educational, and fraternal purposes, and"],[2,"(B) which do not provide for the payment of life, sick, accident, or other benefits."],[1,"(11) Teachers' retirement fund associations of a purely local character, if—"],[2,"(A) no part of their net earnings inures (other than through payment of retirement benefits) to the benefit of any private shareholder or individual, and"],[2,"(B) the income consists solely of amounts received from public taxation, amounts received from assessments on the teaching salaries of members, and income in respect of investments."],[1,"(12)(A) Benevolent life insurance associations of a purely local character, mutual ditch or irrigation companies, mutual or cooperative telephone companies, or like organizations; but only if 85 percent or more of the income consists of amounts collected from members for the sole purpose of meeting losses and expenses."],[1,"(B) In the case of a mutual or cooperative telephone company, subparagraph (A) shall be applied without taking into account any income received or accrued—"],[2,"(i) from a nonmember telephone company for the performance of communication services which involve members of the mutual or cooperative telephone company,"],[2,"(ii) from qualified pole rentals,"],[2,"(iii) from the sale of display listings in a directory furnished to the members of the mutual or cooperative telephone company, or"],[2,"(iv) from the prepayment of a loan under section 306A, 306B, or 311 1 of the Rural Electrification Act of 1936 (as in effect on January 1, 1987)."],[1,"(C) In the case of a mutual or cooperative electric company, subparagraph (A) shall be applied without taking into account any income received or accrued—"],[2,"(i) from qualified pole rentals, or"],[2,"(ii) from any provision or sale of electric energy transmission services or ancillary services if such services are provided on a nondiscriminatory open access basis under an open access transmission tariff approved or accepted by FERC or under an independent transmission provider agreement approved or accepted by FERC (other than income received or accrued directly or indirectly from a member),"],[2,"(iii) from the provision or sale of electric energy distribution services or ancillary services if such services are provided on a nondiscriminatory open access basis to distribute electric energy not owned by the mutual or electric cooperative company—"],[3,"(I) to end-users who are served by distribution facilities not owned by such company or any of its members (other than income received or accrued directly or indirectly from a member), or"],[3,"(II) generated by a generation facility not owned or leased by such company or any of its members and which is directly connected to distribution facilities owned by such company or any of its members (other than income received or accrued directly or indirectly from a member),"],[2,"(iv) from any nuclear decommissioning transaction, or"],[2,"(v) from any asset exchange or conversion transaction."],[1,"(D) For purposes of this paragraph, the term \"qualified pole rental\" means any rental of a pole (or other structure used to support wires) if such pole (or other structure)—"],[2,"(i) is used by the telephone or electric company to support one or more wires which are used by such company in providing telephone or electric services to its members, and"],[2,"(ii) is used pursuant to the rental to support one or more wires (in addition to the wires described in clause (i)) for use in connection with the transmission by wire of electricity or of telephone or other communications."],[1,"For purposes of the preceding sentence, the term \"rental\" includes any sale of the right to use the pole (or other structure)."],[1,"(E) For purposes of subparagraph (C)(ii), the term \"FERC\" means—"],[2,"(i) the Federal Energy Regulatory Commission, or"],[2,"(ii) in the case of any utility with respect to which all of the electricity generated, transmitted, or distributed by such utility is generated, transmitted, distributed, and consumed in the same State, the State agency of such State with the authority to regulate electric utilities."],[1,"(F) For purposes of subparagraph (C)(iv), the term \"nuclear decommissioning transaction\" means—"],[2,"(i) any transfer into a trust, fund, or instrument established to pay any nuclear decommissioning costs if the transfer is in connection with the transfer of the mutual or cooperative electric company's interest in a nuclear power plant or nuclear power plant unit,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/501?type=usc&year=mostrecent&link-type=html"},"head":"§501. Exemption from tax on corporations, certain trusts, etc.","tname":"Internal Revenue Code","by":{"0":"29, 29","1":"28"}},{"t":"reg","label":"45 C.F.R. § 89.3","url":"https://www.ecfr.gov/current/title-45/section-89.3","by":{"0":"10"}},{"t":"case","label":"Abood v. Detroit Board of Education","cite":"431 U.S. 209","y":1977,"id":"1976/75-1153","sc":1,"sum":"A Michigan statute authorizing union representation of local governmental employees permits an \"agency shop\" arrangement, whereby every employee represented by a union, even though not a union member, must pay to the union, as a condition of employment, a service charge equal in amount to union dues. Appellant teachers filed actions (later consolidated) m Michigan state court against appellee Detroit Board of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Agency for International Development v. Alliance for Open Society International, Inc.","cite":"570 U.S. 205","y":2013,"id":"2012/12-10","sc":1,"op":27,"sum":"Concluding that speech uttered involuntarily by legally separate affliates may be attributed to respondents if the affliates are “clearly identifed” with respondents.","sumSrc":"opinion","by":{"1":"passim"}},{"t":"case","label":"Alliance for Open Society International, Inc. v. U.S. Agency for International Development","cite":"254 F. App’x 843","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/254/843/","by":{"1":"12"}},{"t":"case","label":"Alliance for Open Society International, Inc. v. U.S. Agency for International Development","cite":"430 F. Supp. 2d 222","y":2006,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/430/222/","by":{"1":"12"}},{"t":"case","label":"Alliance for Open Society International, Inc. v. U.S. Agency for International Development","cite":"570 F. Supp. 2d 533","y":2008,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/570/533/","by":{"1":"13"}},{"t":"case","label":"Alliance for Open Society International, Inc. v. U.S. Agency for International Development","cite":"651 F.3d 218","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/651/218/","by":{"1":"14"}},{"t":"case","label":"American Needle, Inc. v. NFL","cite":"560 U.S. 183","y":2010,"id":"2009/08-661","sc":1,"op":1,"sum":"Observing that, in many antitrust cases, corporate formalities are “not determinative”.","sumSrc":"opinion","by":{"1":"38"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25, 39"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":1,"ar":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Page(s) Copperweld Corp. v. Independence Tube Corp.","cite":"467 U.S. 752","y":1984,"id":"1983/82-1260","sc":1,"sum":"Petitioner Copperweld and its wholly owned subsidiary, petitioner Regal, are incapable of conspiring with each other for purposes of § 1 of the Sherman Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38, 39"}},{"t":"case","label":"Hecht Co. v. Bowles","cite":"321 U.S. 321","y":1944,"id":"scdb/1943-092","sc":1,"sum":"1. Under § 205 (a) of the Emergency Price Control Act of 1942, the grant of an injunction, upon application of the Administrator and a showing that the defendant has engaged in acts or practices violative of § 4 of the Act, is not mandatory but is in the discretion of the court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Hills v. Gautreaux","cite":"425 U.S. 284","y":1976,"id":"1975/74-1047","sc":1,"op":1,"sum":"A metropolitan area remedy in this case is not impermissible as a matter of law. Milliken v. Bradley, 418 U. S. 717, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 25, 43"}},{"t":"case","label":"Hurley v. Irish-American Gay, Lesbian & Bisexual Group of Boston","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"op":14,"ar":6,"sum":"Holding that a marcher's message will likely be attributed to the parade organizer's, since “every participating unit” in a parade “affects the [overall] message”.","sumSrc":"opinion","by":{"1":"40, 41","2":"17"}},{"t":"case","label":"International Shoe Co. v. Washington","cite":"326 U.S. 310","y":1945,"id":"scdb/1945-002","sc":1,"sum":"Activities within a State of salesmen in the employ of a foreign corporation, exhibiting samples of merchandise and soliciting orders from prospective buyers to be accepted or rejected by the corporation at a point outside the State, were systematic and continuous, and resulted in a large volume of interstate business. A statute of the State requires employers to pay into the state unemployment compensation fund a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Janus v. American Federation of State, County, & Municipal Employees, Council 31","cite":"138 S. Ct. 2448","y":2018,"id":"2017/16-1466","sc":1,"sum":"The Court decided the State of Illinois’ extraction of agency fees from nonconsenting public-sector employees violates the First Amendment; Abood v. Detroit Bd. of Ed., 431 U.S. 209 (1977), which held otherwise, was overruled.","sumSrc":"Oyez","by":{"1":"30, 31, 32, 46, 48"}},{"t":"case","label":"Legal Services Corp. v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"op":3,"sum":"Observing that organizational affliates may provide “alternative channel[s] for expression” by a single speaker.","sumSrc":"opinion","by":{"1":"40"}},{"t":"case","label":"Miami Herald Publishing Co. v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Pacific Gas & Electric Co. v. Public Utilities Commission of California","cite":"475 U.S. 1","y":1986,"id":"1985/84-1044","sc":1,"op":3,"ar":1,"sum":"The Commission's decision must be vacated. Remanded. JUSTICE POWELL, joined by THE CHIEF JUSTICE, JUSTICE BRENNAN, and JUSTICE O'CONNOR, concluded:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Pleasant Grove City, Utah v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"ar":1,"sum":"The Court held that a city's refusal to place an organization's monument in a public park is not a violation the organization's First Amendment rights.","sumSrc":"Oyez","by":{"1":"42","2":"17"}},{"t":"case","label":"PruneYard Shopping Center v. Robins","cite":"447 U.S. 74","y":1980,"id":"1979/79-289","sc":1,"op":4,"sum":"Holding that the Government may require the owner of a private shopping mall to host speech from politically minded pamphleteers.","sumSrc":"opinion","by":{"1":"42"}},{"t":"case","label":"Radio & Television Broadcast Technicians Local Union 1264 v. Broadcast Service of Mobile, Inc.","cite":"380 U.S. 255","y":1965,"id":"1964/61","sc":1,"op":1,"sum":"The National Labor Relations Board declines jurisdiction over radio stations with yearly gross receipts below $100,000, but takes jurisdiction where several nominally separate entities comprise an integrated enterprise of a single employer having receipts in excess of that figure. Where, as here, the criteria of interrelation of operations, common management and ownership, and centralized control of labor relations …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Walker v. Texas Division, Sons of Confederate Veterans, Inc.","cite":"135 S. Ct. 2239","y":2015,"id":"2014/14-144","sc":1,"op":8,"ar":1,"sum":"Texas' specialty license plates constitute government speech that does not require viewpoint neutrality under the First Amendment.","sumSrc":"Oyez","by":{"1":"42","2":"17"}},{"t":"case","label":"West Virginia State Board of Education v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"op":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"1":"1, 30, 31"}},{"t":"case","label":"Whole Woman’s Health v. Hellerstedt","cite":"136 S. Ct. 2292","y":2016,"id":"2015/15-274","sc":1,"sum":"The Court determined that the regulations at issue unconstitutionally imposed an undue burden on women seeking abortions because they created a substantial burden and did not actually serve the stated government interest.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"op":3,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 1055","url":"https://www.law.cornell.edu/uscode/text/15/1055","stext":{"head":"§1055. Use by related companies affecting validity and registration","paras":[[0,"Where a registered mark or a mark sought to be registered is or may be used legitimately by related companies, such use shall inure to the benefit of the registrant or applicant for registration, and such use shall not affect the validity of such mark or of its registration, provided such mark is not used in such manner as to deceive the public. If first use of a mark by a person is controlled by the registrant or applicant for registration of the mark with respect to the nature and quality of the goods or services, such first use shall inure to the benefit of the registrant or applicant, as the case may be."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1055?type=usc&year=mostrecent&link-type=html"},"head":"§1055. Use by related companies affecting validity and registration","tname":"Commerce and Trade","by":{"1":"38","2":"15"}},{"t":"usc","label":"22 U.S.C. § 2151u","url":"https://www.law.cornell.edu/uscode/text/22/2151u","by":{"1":"9"}},{"t":"reg","label":"2 C.F.R. § 200.330","url":"https://www.ecfr.gov/current/title-2/section-200.330","by":{"1":"10"}},{"t":"reg","label":"15 C.F.R. § 760.1","url":"https://www.ecfr.gov/current/title-15/section-760.1","by":{"1":"38"}},{"t":"reg","label":"45 C.F.R. § 89.1","url":"https://www.ecfr.gov/current/title-45/section-89.1","by":{"1":"13"}},{"t":"reg","label":"70 Fed. Reg. 29,759","url":"https://www.govinfo.gov/link/fr/70/29759","by":{"1":"11"}},{"t":"case","label":"Arkansas Game & Fish Comm’n v. United States","cite":"568 U.S. 23","y":2012,"id":"2012/11-597","sc":1,"op":1,"sum":"The Court held the Fifth Amendment's Taking Clause could be enacted when a temporary flood regime destroyed property.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Bluman v. FEC","cite":"800 F. Supp. 2d 281","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/800/281/","op":1,"sum":"Noting consensus “that the government may bar foreign citizens abroad from making contributions” in U.S. elections.","sumSrc":"brief:2","by":{"2":"19"}},{"t":"case","label":"Copperweld Corp. v. Independence Tube Corp.","cite":"467 US. 752","y":1984,"url":"https://www.courtlistener.com/c/US./467/752/","by":{"2":"15"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Rostker v. Goldberg","cite":"453 U.S. 57","y":1981,"id":"1980/80-251","sc":1,"sum":"In a 6-to-3 decision, the Court held that Congress's decision to exempt women from registration \"was not the 'accidental by-product of a traditional way of thinking about females'\" and did not violate the Due Process Clause. The Court found that men and women, because of combat restrictions on women, were not \"similarly situated\" for the purposes of draft registration.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"op":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"usc","label":"15 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/15/1","stext":{"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","paras":[[0,"Every contract, combination in the form of trust or otherwise, or conspiracy, in restraint of trade or commerce among the several States, or with foreign nations, is declared to be illegal. Every person who shall make any contract or engage in any combination or conspiracy hereby declared to be illegal shall be deemed guilty of a felony, and, on conviction thereof, shall be punished by fine not exceeding $100,000,000 if a corporation, or, if any other person, $1,000,000, or by imprisonment not exceeding 10 years, or by both said punishments, in the discretion of the court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. Trusts, etc., in restraint of trade illegal; penalty","tname":"Commerce and Trade","by":{"2":"15"}},{"t":"reg","label":"72 Fed. Reg. 41,076","url":"https://www.govinfo.gov/link/fr/72/41076","by":{"2":"7, 21"}},{"t":"reg","label":"75 Fed. Reg. 18,760","url":"https://www.govinfo.gov/link/fr/75/18760","by":{"2":"7, 18"}}]};